// Squeeze Lens - a round lens that squeezes the image along one axis and
// stretches it along the other (the area is preserved), while the axes turn
// and the squeeze breathes. Parametric (u,v), animated. Works on the loaded
// image, or on the dock checkerboard when no image is loaded.
//
// SEAM-FREE: outside the lens the image is left exactly as it is, so the
// texture closes wherever the image itself closes (always, with the
// checkerboard). The lens is measured from the NEAREST copy of its center,
// so it can even sit on a seam.
// OVERLAY = 1 draws the rim of the lens, the ellipse that a circle of the
// image becomes, and the two axes (stretch and squeeze); OVERLAY = 0 shows
// only the deformation.

const float CENTER_U = 0.5;    // center of the lens (turns along u)
const float CENTER_V = 0.5;    // center of the lens (turns along v)
const float LENS     = 0.3;    // lens radius in turns                  [0.05 .. 0.45]
const float ASPECT   = 1.0;    // >1 squeezes the lens along u          [0.3 .. 3]
const float SQUEEZE  = 0.6;    // log of the stretch factor             [0 .. 1.2]
const float BREATH   = 0.4;    // pulse of the squeeze (0 = steady)     [0 .. 1]
const float SPIN     = 0.08;   // turns per second of the axes
const float OVERLAY  = 1.0;    // 1 = draw rim, ellipse and axes; 0 = image only
const vec3  RIM_COLOR     = vec3(0.92, 0.95, 1.0);
const vec3  STRETCH_COLOR = vec3(1.0, 0.82, 0.2);
const vec3  SQUEEZE_COLOR = vec3(0.2, 0.85, 1.0);
const vec3  ELLIPSE_COLOR = vec3(1.0, 0.4, 0.85);

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    float time = iTime;

    vec2 d0 = uv - vec2(CENTER_U, CENTER_V);
    d0 -= floor(d0 + 0.5);                          // nearest copy across the seams
    vec2 d = d0 * vec2(ASPECT, 1.0);
    float rho = length(d) / LENS;                   // 1 = rim of the lens

    // axes of the squeeze and its amount
    float a = TAU * SPIN * time;
    vec2 ax = vec2(cos(a), sin(a));                 // stretch axis
    vec2 ay = vec2(-ax.y, ax.x);                    // squeeze axis
    float k = SQUEEZE * (1.0 - BREATH + BREATH * (0.5 + 0.5 * sin(1.1 * time)));

    // read the image at (x e^-k, y e^k) in the axes frame: it shows
    // stretched e^k times along ax and squeezed as much along ay
    vec2 inAxes = vec2(dot(d, ax), dot(d, ay));
    vec2 read = inAxes * vec2(exp(-k), exp(k));
    vec2 dS = read.x * ax + read.y * ay;
    float w = smoothstep(1.0, 0.55, rho);           // full inside, none outside
    vec2 dL = mix(d, dS, w);
    vec2 src = uv + vec2((dL.x - d.x) / ASPECT, dL.y - d.y);
    vec3 col = texture(iChannel0, src).rgb;

    if (OVERLAY > 0.5) {
        // pixel size in lens units; fract(uv + 0.5) ignores the seam jump
        vec2 fw = min(fwidth(uv), fwidth(fract(uv + 0.5)));
        float px = max(fw.x * ASPECT, fw.y) / LENS;
        float inside = 1.0 - smoothstep(0.98, 1.0, rho);

        float rim = 1.0 - smoothstep(px, 2.5 * px, abs(rho - 1.0));
        float lineA = (1.0 - smoothstep(px, 2.5 * px, abs(inAxes.y) / LENS)) * inside;
        float lineB = (1.0 - smoothstep(px, 2.5 * px, abs(inAxes.x) / LENS)) * inside;
        // a circle of radius 0.5 in the image, as the lens shows it
        float ell = length(read) / LENS;
        float lineE = (1.0 - smoothstep(1.0, 2.5, abs(ell - 0.5) / max(fwidth(ell), 1.0e-5))) * inside * w;

        col = mix(col, STRETCH_COLOR, 0.9 * lineA);
        col = mix(col, SQUEEZE_COLOR, 0.9 * lineB);
        col = mix(col, ELLIPSE_COLOR, 0.9 * lineE);
        col = mix(col, RIM_COLOR, 0.8 * rim);
    }
    fragColor = vec4(col, 1.0);
}
